+int testSwitchExpr(Object o1, Object o2) {
+    int result = 0;
+    return switch(o1) {
+        case null:
+            result += 1;
+        case String _ when o2 != null:
+            if (o2 instanceof Integer i) {
+                result += i;
+            }
+            result += 10;
+        default:
+            result += 100;
+            yield result;
+    };
+}
